import{i as e,r as t,s as n,t as r}from"./app-iekWC344.js";var i=JSON.parse(`{"path":"/guide/sql-postgresql/","title":"SQL и PostgreSQL","lang":"ru-RU","frontmatter":{"prev":"/guide/docker/best-practices.md","next":"/guide/sql-postgresql/tests.md"},"git":{"updatedTime":1792183814000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"b187982dd11c4164dfa6d7ad654568e886c41269","time":1792183814000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"fixes"}]},"filePathRelative":"guide/sql-postgresql/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="sql-и-postgresql" tabindex="-1"><a class="header-anchor" href="#sql-и-postgresql"><span>SQL и PostgreSQL</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Подключить Task Manager API к PostgreSQL из Docker Compose через <code>database/sql</code> и <code>pgx</code>, хранить структуру БД в SQL-миграциях Goose, реализовать CRUD-репозиторий задач с параметризованными запросами, применять context в операциях БД и проверять всё интеграционными тестами против отдельной тестовой базы.</p><p>В предыдущей главе PostgreSQL уже запущен как сервис <code>postgres</code> в Docker Compose. Сейчас он перестаёт быть только инфраструктурой: API подключается к нему и заменяет in-memory <code>TaskStore</code> на PostgreSQL-репозиторий.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Gin handler → TaskService → TaskRepository → database/sql → pgx → PostgreSQL</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Service по-прежнему зависит от интерфейса репозитория. Благодаря этому HTTP-слой Gin и бизнес-правила не должны знать SQL-запросы, а unit-тесты service могут использовать fake repository.</p><h2 id="postgresql-и-dbeaver" tabindex="-1"><a class="header-anchor" href="#postgresql-и-dbeaver"><span>PostgreSQL и DBeaver</span></a></h2><p>Поднимите окружение из прошлой главы:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> examples/task-manager-api</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"><span class="token function">docker</span> compose <span class="token function">ps</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Внутри Docker Compose приложение подключается к host <code>postgres</code>. DBeaver запускается на вашем компьютере, поэтому для него указывайте опубликованный локальный адрес:</p><table><thead><tr><th>Поле DBeaver</th><th>Значение из <code>.env</code> по умолчанию</th></tr></thead><tbody><tr><td>Host</td><td><code>localhost</code></td></tr><tr><td>Port</td><td><code>5432</code> (<code>POSTGRES_PORT</code>)</td></tr><tr><td>Database</td><td><code>task_manager</code> (<code>POSTGRES_DB</code>)</td></tr><tr><td>Username</td><td><code>task_manager</code> (<code>POSTGRES_USER</code>)</td></tr><tr><td>Password</td><td><code>local-development-only</code> (<code>POSTGRES_PASSWORD</code>)</td></tr></tbody></table><p>В DBeaver выберите <strong>New Database Connection → PostgreSQL</strong>, заполните поля и нажмите <strong>Test Connection</strong>. Если драйвер PostgreSQL ещё не скачан, DBeaver предложит сделать это сам.</p><p>Для учебного Docker Compose TLS не настроен. Если DBeaver требует SSL, на вкладке <strong>SSL</strong> выберите режим <code>disable</code>. В production режим TLS определяется требованиями инфраструктуры, а не этой локальной настройкой.</p><p>После выполнения миграций раскройте соединение в Database Navigator:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Databases → task_manager → Schemas → public → Tables → tasks</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Через DBeaver удобно просматривать таблицы, запускать <code>SELECT</code> и проверять результат миграций. Он не заменяет миграции: изменение таблицы вручную в UI не попадёт в Git и не повторится у другого разработчика.</p><div class="hint-container tip"><p class="hint-container-title">Два разных hostname</p><p>Из API-container подключайтесь к <code>postgres:5432</code>. Из DBeaver на компьютере — к <code>localhost:5432</code>. <code>localhost</code> внутри container означает сам container, а не сервис PostgreSQL.</p></div><h2 id="database-sql-и-pgx" tabindex="-1"><a class="header-anchor" href="#database-sql-и-pgx"><span><code>database/sql</code> и pgx</span></a></h2><p><code>database/sql</code> — стандартный пакет Go с общим API для SQL-баз. Он управляет пулом соединений, <code>QueryContext</code>, <code>ExecContext</code>, <code>BeginTx</code> и транзакциями, но сам не умеет разговаривать с PostgreSQL. Для этого нужен драйвер.</p><p>Используем <code>pgx</code> через адаптер <code>stdlib</code>:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go get github.com/jackc/pgx/v5/stdlib</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Зарегистрируйте драйвер blank-импортом один раз в пакете, где открываете базу:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;database/sql&quot;</span></span>
<span class="line">	<span class="token boolean">_</span> <span class="token string">&quot;github.com/jackc/pgx/v5/stdlib&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Пустой идентификатор означает: пакет нужен из-за side effect — он регистрирует драйвер с именем <code>pgx</code>. Теперь можно вызвать:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">db<span class="token punctuation">,</span> err <span class="token operator">:=</span> sql<span class="token punctuation">.</span><span class="token function">Open</span><span class="token punctuation">(</span><span class="token string">&quot;pgx&quot;</span><span class="token punctuation">,</span> databaseURL<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;открыть PostgreSQL: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>sql.Open</code> не гарантирует, что соединение с базой уже установлено. Он создаёт <code>*sql.DB</code> — пул будущих соединений. Реальную доступность проверяет <code>PingContext</code>.</p><h2 id="открытие-и-настроика-пула" tabindex="-1"><a class="header-anchor" href="#открытие-и-настроика-пула"><span>Открытие и настройка пула</span></a></h2><p>Создайте функцию подключения:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">Open</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> databaseURL <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>sql<span class="token punctuation">.</span>DB<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	db<span class="token punctuation">,</span> err <span class="token operator">:=</span> sql<span class="token punctuation">.</span><span class="token function">Open</span><span class="token punctuation">(</span><span class="token string">&quot;pgx&quot;</span><span class="token punctuation">,</span> databaseURL<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;открыть PostgreSQL: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	db<span class="token punctuation">.</span><span class="token function">SetMaxOpenConns</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span></span>
<span class="line">	db<span class="token punctuation">.</span><span class="token function">SetMaxIdleConns</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span></span>
<span class="line">	db<span class="token punctuation">.</span><span class="token function">SetConnMaxLifetime</span><span class="token punctuation">(</span><span class="token number">30</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Minute<span class="token punctuation">)</span></span>
<span class="line">	db<span class="token punctuation">.</span><span class="token function">SetConnMaxIdleTime</span><span class="token punctuation">(</span><span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Minute<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	pingCtx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> context<span class="token punctuation">.</span><span class="token function">WithTimeout</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token number">5</span><span class="token operator">*</span>time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> <span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> db<span class="token punctuation">.</span><span class="token function">PingContext</span><span class="token punctuation">(</span>pingCtx<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		db<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;проверить PostgreSQL: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> db<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Значения пула зависят от нагрузки и ограничений PostgreSQL. Эти числа — безопасный старт для учебного API, а не универсальный production-рецепт. Общее число подключений всех экземпляров API должно помещаться в лимит <code>max_connections</code> базы.</p><p>Если <code>PingContext</code> не удался, закрывайте уже созданный пул до возврата ошибки. В <code>main</code> после graceful shutdown передайте <code>db</code> в <code>closeAll</code>, который появился в прошлой главе:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">defer</span> db<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>В реальном <code>run</code> закрытие должно идти <strong>после</strong> <code>server.Shutdown</code>, чтобы активный handler не потерял базу во время запроса.</p><h2 id="database-url" tabindex="-1"><a class="header-anchor" href="#database-url"><span><code>DATABASE_URL</code></span></a></h2><p>Внутри Compose строка подключения имеет вид:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">postgresql://task_manager:local-development-only@postgres:5432/task_manager?sslmode=disable</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Для запуска кода на компьютере и DBeaver hostname меняется на <code>localhost</code>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">postgresql://task_manager:local-development-only@localhost:5432/task_manager?sslmode=disable</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>sslmode=disable</code> допустим только для локального учебного окружения Docker. В production способ TLS-подключения выбирается требованиями инфраструктуры; не переносите это значение без проверки.</p><p>Добавьте в локальный <code>.env</code>:</p><div class="language-dotenv line-numbers-mode" data-highlighter="prismjs" data-ext="dotenv"><pre><code class="language-dotenv"><span class="line">DATABASE_URL=postgresql://task_manager:local-development-only@postgres:5432/task_manager?sslmode=disable</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Значение внутри API-container использует <code>postgres</code>. Не выводите полный <code>DATABASE_URL</code> в лог: в нём есть пароль.</p><h2 id="миграции-goose" tabindex="-1"><a class="header-anchor" href="#миграции-goose"><span>Миграции Goose</span></a></h2><p>Миграция — версия изменения схемы БД, которая хранится в Git и применяется одинаково у каждого разработчика и на CI. Не создавайте таблицы вручную только через DBeaver или <code>psql</code>: остальным окружениям это изменение не достанется.</p><p>Добавьте библиотеку и CLI Goose:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go get github.com/pressly/goose/v3</span>
<span class="line">go <span class="token function">install</span> github.com/pressly/goose/v3/cmd/goose@latest</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Создайте каталог <code>migrations</code> и первую миграцию:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">mkdir</span> migrations</span>
<span class="line">goose <span class="token parameter variable">-dir</span> migrations create create_tasks_table sql</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Файл будет иметь timestamp в имени. Например, <code>migrations/20261014120000_create_tasks_table.sql</code>:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token comment">-- +goose Up</span></span>
<span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> tasks <span class="token punctuation">(</span></span>
<span class="line">    id BIGSERIAL <span class="token keyword">PRIMARY</span> <span class="token keyword">KEY</span><span class="token punctuation">,</span></span>
<span class="line">    title <span class="token keyword">TEXT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">CHECK</span> <span class="token punctuation">(</span>char_length<span class="token punctuation">(</span>btrim<span class="token punctuation">(</span>title<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    priority <span class="token keyword">SMALLINT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">CHECK</span> <span class="token punctuation">(</span>priority <span class="token operator">BETWEEN</span> <span class="token number">1</span> <span class="token operator">AND</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    completed <span class="token keyword">BOOLEAN</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token boolean">FALSE</span><span class="token punctuation">,</span></span>
<span class="line">    created_at TIMESTAMPTZ <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token function">NOW</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    updated_at TIMESTAMPTZ <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token function">NOW</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">INDEX</span> tasks_completed_priority_idx <span class="token keyword">ON</span> tasks <span class="token punctuation">(</span>completed<span class="token punctuation">,</span> priority<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- +goose Down</span></span>
<span class="line"><span class="token keyword">DROP</span> <span class="token keyword">TABLE</span> tasks<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В <code>Up</code> находятся действия применения, в <code>Down</code> — откат именно этой миграции. После того как миграция попала в общую среду, не переписывайте её историю. Создайте следующую миграцию для нового изменения схемы.</p><p>Примените и проверьте миграции внутри API-container или на хосте с корректным <code>DATABASE_URL</code>:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">goose <span class="token parameter variable">-dir</span> migrations postgres <span class="token string">&quot;<span class="token variable">$DATABASE_URL</span>&quot;</span> status</span>
<span class="line">goose <span class="token parameter variable">-dir</span> migrations postgres <span class="token string">&quot;<span class="token variable">$DATABASE_URL</span>&quot;</span> up</span>
<span class="line">goose <span class="token parameter variable">-dir</span> migrations postgres <span class="token string">&quot;<span class="token variable">$DATABASE_URL</span>&quot;</span> status</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Goose создаёт таблицу <code>goose_db_version</code>. В DBeaver убедитесь, что есть и <code>tasks</code>, и <code>goose_db_version</code>.</p><h2 id="модель-sql-и-go" tabindex="-1"><a class="header-anchor" href="#модель-sql-и-go"><span>Модель SQL и Go</span></a></h2><p>Добавим время создания и обновления в модель, чтобы репозиторий мог читать их из PostgreSQL:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Task <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	ID        <span class="token builtin">int64</span>      <span class="token string">\`json:&quot;id&quot;\`</span></span>
<span class="line">	Title     <span class="token builtin">string</span>     <span class="token string">\`json:&quot;title&quot;\`</span></span>
<span class="line">	Priority  <span class="token builtin">int</span>        <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line">	Completed <span class="token builtin">bool</span>       <span class="token string">\`json:&quot;completed&quot;\`</span></span>
<span class="line">	CreatedAt time<span class="token punctuation">.</span>Time  <span class="token string">\`json:&quot;created_at&quot;\`</span></span>
<span class="line">	UpdatedAt time<span class="token punctuation">.</span>Time  <span class="token string">\`json:&quot;updated_at&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Выбирайте <code>BIGSERIAL</code> и <code>int64</code> согласованно. PostgreSQL возвращает время с временной зоной в <code>time.Time</code>. JSON-кодировщик отдаст его в формате RFC 3339.</p><p>Для <code>INSERT ... RETURNING</code> создайте задачу и получите значения, которые назначила база:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> createTaskQuery <span class="token operator">=</span> <span class="token string">\`</span>
<span class="line">INSERT INTO tasks (title, priority)</span>
<span class="line">VALUES ($1, $2)</span>
<span class="line">RETURNING id, title, priority, completed, created_at, updated_at\`</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">Create</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> input task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> created task<span class="token punctuation">.</span>Task</span>
<span class="line">	err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryRowContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> createTaskQuery<span class="token punctuation">,</span> input<span class="token punctuation">.</span>Title<span class="token punctuation">,</span> input<span class="token punctuation">.</span>Priority<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Completed<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>UpdatedAt<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;создать задачу: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> created<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>QueryRowContext</code> подходит, когда ожидается ровно одна строка. <code>Scan</code> выполняет запрос и считывает результат. Порядок переменных должен совпадать с порядком столбцов в <code>RETURNING</code>.</p><h2 id="параметры-и-sql-инъекции" tabindex="-1"><a class="header-anchor" href="#параметры-и-sql-инъекции"><span>Параметры и SQL-инъекции</span></a></h2><p>Никогда не собирайте значения пользователя через <code>fmt.Sprintf</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token comment">// Уязвимо и неверно:</span></span>
<span class="line"><span class="token comment">// query := fmt.Sprintf(&quot;SELECT id FROM tasks WHERE title = &#39;%s&#39;&quot;, title)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Используйте placeholders PostgreSQL <code>$1</code>, <code>$2</code> и передавайте значения отдельными аргументами:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> getTaskQuery <span class="token operator">=</span> <span class="token string">\`</span>
<span class="line">SELECT id, title, priority, completed, created_at, updated_at</span>
<span class="line">FROM tasks</span>
<span class="line">WHERE id = $1\`</span></span>
<span class="line"></span>
<span class="line">row <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryRowContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> getTaskQuery<span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Драйвер сам передаёт <code>id</code> как значение, а не как часть SQL-синтаксиса. Placeholders применяются к <strong>данным</strong>, но не к именам таблиц, столбцов и <code>ORDER BY</code>-направлениям. Если позже понадобится динамическая сортировка, выбирайте имя столбца из закрытого whitelist, а не из строки клиента.</p><h2 id="get-list-и-sql-errnorows" tabindex="-1"><a class="header-anchor" href="#get-list-и-sql-errnorows"><span><code>Get</code>, <code>List</code> и <code>sql.ErrNoRows</code></span></a></h2><p><code>Get</code> преобразует отсутствие строки в доменную ошибку:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> ErrTaskNotFound <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;задача не найдена&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">Get</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> id <span class="token builtin">int64</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> current task<span class="token punctuation">.</span>Task</span>
<span class="line">	err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryRowContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> getTaskQuery<span class="token punctuation">,</span> id<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Completed<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>UpdatedAt<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> sql<span class="token punctuation">.</span>ErrNoRows<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;получить задачу %d: %w&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> current<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>HTTP layer затем преобразует <code>ErrTaskNotFound</code> в <code>404</code>, не зная о <code>sql.ErrNoRows</code>.</p><p>Для нескольких строк используйте <code>QueryContext</code>. Всегда закрывайте <code>rows</code> и проверяйте <code>rows.Err()</code> после цикла:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> listTasksQuery <span class="token operator">=</span> <span class="token string">\`</span>
<span class="line">SELECT id, title, priority, completed, created_at, updated_at</span>
<span class="line">FROM tasks</span>
<span class="line">ORDER BY id\`</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">List</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	rows<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> listTasksQuery<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;получить список задач: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">defer</span> rows<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	tasks <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">for</span> rows<span class="token punctuation">.</span><span class="token function">Next</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">var</span> current task<span class="token punctuation">.</span>Task</span>
<span class="line">		<span class="token keyword">if</span> err <span class="token operator">:=</span> rows<span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>Completed<span class="token punctuation">,</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">,</span></span>
<span class="line">			<span class="token operator">&amp;</span>current<span class="token punctuation">.</span>UpdatedAt<span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;прочитать задачу: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		tasks <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>tasks<span class="token punctuation">,</span> current<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> rows<span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;обойти список задач: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> tasks<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Пустой список возвращается как <code>[]</code>, а не <code>null</code>, поскольку слайс создаётся через <code>make</code>.</p><h2 id="update-и-delete" tabindex="-1"><a class="header-anchor" href="#update-и-delete"><span>Update и Delete</span></a></h2><p>Завершим задачу через <code>UPDATE ... RETURNING</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> completeTaskQuery <span class="token operator">=</span> <span class="token string">\`</span>
<span class="line">UPDATE tasks</span>
<span class="line">SET completed = TRUE, updated_at = NOW()</span>
<span class="line">WHERE id = $1</span>
<span class="line">RETURNING id, title, priority, completed, created_at, updated_at\`</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">Complete</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> id <span class="token builtin">int64</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> completed task<span class="token punctuation">.</span>Task</span>
<span class="line">	err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryRowContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> completeTaskQuery<span class="token punctuation">,</span> id<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>Completed<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>completed<span class="token punctuation">.</span>UpdatedAt<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> sql<span class="token punctuation">.</span>ErrNoRows<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;завершить задачу %d: %w&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> completed<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для удаления обычно достаточно <code>ExecContext</code> и проверки числа затронутых строк:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">Delete</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> id <span class="token builtin">int64</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	result<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">ExecContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">\`DELETE FROM tasks WHERE id = $1\`</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;удалить задачу %d: %w&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	affected<span class="token punctuation">,</span> err <span class="token operator">:=</span> result<span class="token punctuation">.</span><span class="token function">RowsAffected</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;узнать число удалённых задач: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> affected <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="context-в-sql-операциях" tabindex="-1"><a class="header-anchor" href="#context-в-sql-операциях"><span>Context в SQL-операциях</span></a></h2><p>Используйте методы с суффиксом <code>Context</code>: <code>PingContext</code>, <code>QueryContext</code>, <code>QueryRowContext</code>, <code>ExecContext</code>, <code>BeginTx</code>. Тогда отменённый HTTP-запрос или дедлайн не оставит бессмысленную SQL-операцию работать дальше.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">createdTask<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> input<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не подменяйте полученный context на <code>context.Background()</code> внутри репозитория. Исключение — отдельный lifecycle context при штатном завершении процесса, но это задача <code>main</code>, а не CRUD-метода.</p><h2 id="транзакции" tabindex="-1"><a class="header-anchor" href="#транзакции"><span>Транзакции</span></a></h2><p>Транзакция нужна, когда несколько изменений должны пройти все вместе или ни одно. Например, создадим задачу и запись аудита:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>repository <span class="token operator">*</span>Repository<span class="token punctuation">)</span> <span class="token function">CreateWithAudit</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> input task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	tx<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">BeginTx</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;начать транзакцию: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">defer</span> tx<span class="token punctuation">.</span><span class="token function">Rollback</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// после Commit вернёт sql.ErrTxDone и будет проигнорирован</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> created task<span class="token punctuation">.</span>Task</span>
<span class="line">	err <span class="token operator">=</span> tx<span class="token punctuation">.</span><span class="token function">QueryRowContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> createTaskQuery<span class="token punctuation">,</span> input<span class="token punctuation">.</span>Title<span class="token punctuation">,</span> input<span class="token punctuation">.</span>Priority<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> <span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Title<span class="token punctuation">,</span> <span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span> <span class="token operator">&amp;</span>created<span class="token punctuation">.</span>Completed<span class="token punctuation">,</span></span>
<span class="line">		<span class="token operator">&amp;</span>created<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">,</span> <span class="token operator">&amp;</span>created<span class="token punctuation">.</span>UpdatedAt<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;создать задачу: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> tx<span class="token punctuation">.</span><span class="token function">ExecContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span></span>
<span class="line">		<span class="token string">\`INSERT INTO task_audit (task_id, action) VALUES ($1, $2)\`</span><span class="token punctuation">,</span></span>
<span class="line">		created<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> <span class="token string">&quot;created&quot;</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;создать аудит: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> tx<span class="token punctuation">.</span><span class="token function">Commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;зафиксировать транзакцию: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">return</span> created<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не начинайте транзакцию вокруг каждого одиночного <code>INSERT</code> или <code>UPDATE</code>: PostgreSQL и так выполняет одиночную SQL-команду атомарно. <code>task_audit</code> здесь появится только в отдельной миграции, если такая функция действительно нужна.</p><h2 id="интеграционные-тесты-через-docker-compose" tabindex="-1"><a class="header-anchor" href="#интеграционные-тесты-через-docker-compose"><span>Интеграционные тесты через Docker Compose</span></a></h2><p>Unit-тесты service остаются быстрыми и используют fake repository. PostgreSQL-репозиторий нужно также проверять против настоящей БД: SQL-синтаксис, типы, constraints и миграции нельзя надёжно подтвердить только mock-объектом.</p><p>Поднимите PostgreSQL из Compose и создайте отдельную тестовую БД один раз:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> examples/task-manager-api</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span> postgres</span>
<span class="line"><span class="token function">docker</span> compose <span class="token builtin class-name">exec</span> postgres createdb <span class="token parameter variable">-U</span> task_manager task_manager_test</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Задайте <strong>только</strong> тестовую строку подключения:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">TEST_DATABASE_URL</span><span class="token operator">=</span><span class="token string">&#39;postgresql://task_manager:local-development-only@localhost:5432/task_manager_test?sslmode=disable&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Тесты никогда не должны получать <code>DATABASE_URL</code> production или development-базы. Проверяйте, что имя БД оканчивается на <code>_test</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">testDatabaseURL</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">	t<span class="token punctuation">.</span><span class="token function">Helper</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	databaseURL <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">Getenv</span><span class="token punctuation">(</span><span class="token string">&quot;TEST_DATABASE_URL&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> databaseURL <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Skip</span><span class="token punctuation">(</span><span class="token string">&quot;TEST_DATABASE_URL не задан&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>strings<span class="token punctuation">.</span><span class="token function">Contains</span><span class="token punctuation">(</span>databaseURL<span class="token punctuation">,</span> <span class="token string">&quot;_test&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;TEST_DATABASE_URL должен указывать на отдельную тестовую БД&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">return</span> databaseURL</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Примените к ней миграции в <code>TestMain</code> или до тестового запуска:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">goose <span class="token parameter variable">-dir</span> migrations postgres <span class="token string">&quot;<span class="token variable">$TEST_DATABASE_URL</span>&quot;</span> up</span>
<span class="line">go <span class="token builtin class-name">test</span> <span class="token parameter variable">-tags</span><span class="token operator">=</span>integration ./internal/postgresrepo/<span class="token punctuation">..</span>.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Используйте build tag, чтобы обычный <code>go test ./...</code> не требовал запущенную БД:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token comment">//go:build integration</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> postgresrepo_test</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Перед каждым тестом очищайте только тестовую таблицу:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">truncateTasks</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">,</span> db <span class="token operator">*</span>sql<span class="token punctuation">.</span>DB<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	t<span class="token punctuation">.</span><span class="token function">Helper</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> db<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span><span class="token string">\`TRUNCATE tasks RESTART IDENTITY\`</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;очистить tasks: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Тест <code>Create</code> проверяет реальную вставку и чтение:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestRepositoryCreateAndGet</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	db <span class="token operator">:=</span> <span class="token function">openTestDatabase</span><span class="token punctuation">(</span>t<span class="token punctuation">)</span></span>
<span class="line">	t<span class="token punctuation">.</span><span class="token function">Cleanup</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> db<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token function">truncateTasks</span><span class="token punctuation">(</span>t<span class="token punctuation">,</span> db<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	repository <span class="token operator">:=</span> postgresrepo<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>db<span class="token punctuation">)</span></span>
<span class="line">	created<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">{</span></span>
<span class="line">		Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Create: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> created<span class="token punctuation">.</span>ID <span class="token operator">==</span> <span class="token number">0</span> <span class="token operator">||</span> created<span class="token punctuation">.</span>CreatedAt<span class="token punctuation">.</span><span class="token function">IsZero</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;создана некорректная задача: %+v&quot;</span><span class="token punctuation">,</span> created<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	got<span class="token punctuation">,</span> err <span class="token operator">:=</span> repository<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> created<span class="token punctuation">.</span>ID<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Get: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> got<span class="token punctuation">.</span>Title <span class="token operator">!=</span> created<span class="token punctuation">.</span>Title <span class="token operator">||</span> got<span class="token punctuation">.</span>Priority <span class="token operator">!=</span> created<span class="token punctuation">.</span>Priority <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Get = %+v, ожидалась %+v&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">,</span> created<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не запускайте такие тесты с <code>t.Parallel</code>, если они используют одну БД и <code>TRUNCATE</code>. Для полной изоляции параллельных интеграционных тестов понадобятся отдельные схемы или базы — это отдельная задача.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="думать-что-sql-open-уже-подключился" tabindex="-1"><a class="header-anchor" href="#думать-что-sql-open-уже-подключился"><span>Думать, что <code>sql.Open</code> уже подключился</span></a></h3><p><code>sql.Open</code> может успешно вернуть pool при недоступной БД. Проверяйте доступность через <code>PingContext</code> с timeout при старте.</p><h3 id="подставлять-значения-в-sql-строкои" tabindex="-1"><a class="header-anchor" href="#подставлять-значения-в-sql-строкои"><span>Подставлять значения в SQL строкой</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">query <span class="token operator">:=</span> <span class="token string">&quot;DELETE FROM tasks WHERE id = &quot;</span> <span class="token operator">+</span> id</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Такой код уязвим и ломается на форматах данных. Используйте <code>$1</code> и аргументы <code>ExecContext</code>.</p><h3 id="не-закрывать-rows" tabindex="-1"><a class="header-anchor" href="#не-закрывать-rows"><span>Не закрывать <code>rows</code></span></a></h3><p>Незакрытые <code>rows</code> удерживают соединение пула. После успешного <code>QueryContext</code> сразу пишите <code>defer rows.Close()</code> и после обхода проверяйте <code>rows.Err()</code>.</p><h3 id="запускать-тесты-против-development-бд" tabindex="-1"><a class="header-anchor" href="#запускать-тесты-против-development-бд"><span>Запускать тесты против development-БД</span></a></h3><p><code>TRUNCATE</code> в тесте может уничтожить ваши локальные данные. Используйте отдельную <code>task_manager_test</code>, <code>TEST_DATABASE_URL</code> и защитную проверку имени базы.</p><h3 id="редактировать-уже-примененную-миграцию" tabindex="-1"><a class="header-anchor" href="#редактировать-уже-примененную-миграцию"><span>Редактировать уже применённую миграцию</span></a></h3><p>У другого разработчика или CI эта версия могла уже примениться. Создайте новую миграцию, которая изменяет схему вперёд.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Task Manager хранит задачи в PostgreSQL, а схема воспроизводимо развивается через Goose. В следующей главе настроим CI/CD и деплой: тесты, проверку образа, secrets и health-check после доставки приложения.</p>`,118)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};